mapper.select:
SELECT  FROM event_info E

	E.EVENT_NO = #{eventNo}
	AND DATE(E.EVENT_START_DATE) >= #{eventStartDate}
	AND DATE(E.EVENT_END_DATE) <= #{eventEndDate}
	AND (CASE WHEN NOW() > E.EVENT_END_DATE THEN 'ENDED' ELSE 'ONGOING' END) IN #{item}
	AND E.USE_YN IN #{item}
	AND E.DISPLAY_YN IN #{item}

ORDER BY E.EVENT_NO DESC

mapper.update:
UPDATE event_info SET EVENT_TITLE = #{eventTitle}, USE_YN = #{useYn}, DISPLAY_YN = #{displayYn},
	EVENT_START_DATE = #{eventStartDate}, EVENT_END_DATE = #{eventEndDate},
	UPDT_DATE = NOW(), UPDT_ID = #{updtId}
WHERE EVENT_NO = #{eventNo}
